#!/usr/bin/env python3
"""Some portions generated by Codex. Inclusive sampled frames, not wall-time or exact invocation counts."""
import collections,json,pathlib,sys
out={}
patterns={
 'threadlocal_map':('java.lang.ThreadLocal','java/lang/ThreadLocal'),
 'cancellation_probe':('NativeCancellation','NativeRecordCancellation','CancellationSignal','LmdbNativeProbeDeadline','pollCancellation'),
 'lifetime_read_replay':('RepositoryValueIteration','ValueResolutionScope','QueryExecutionContext','ReadExposureScope','CapturedReadContext'),
 'value_decode_memo':('NativeValueMemo','LmdbNativeValueCodec','ValueStore','LmdbValue','CompressedValueOverlay'),
 'binding_copy':('BindingSet','Binding.getValue'),
 'native_ir':('KernelInterpreter','KernelRowCursor','codegen','Janino'),
 'record_owner':('NativeRecordCancellation.check','LmdbRecordIterator.checkRecordCancellation','LmdbRecordIterator.bindCancellation','LmdbRecordIterator.reset'),
 'record_scan':('LmdbRecordIterator','RetainedNativeProbe','LmdbNativeKernelScanner'),
 'memory_stack':('org.lwjgl.system.MemoryStack',),
 'distinct':('Distinct','TupleTable'),
}
for p in sorted(pathlib.Path(sys.argv[1]).glob('*.samples.json')):
    samples=json.loads(p.read_text())['recording']['events']
    leaves=collections.Counter(); frames=collections.Counter(); categories=collections.Counter(); stacks=collections.Counter()
    callers=collections.Counter()
    count=0
    for e in samples:
        v=e['values']; thread=v.get('sampledThread') or v.get('eventThread') or {}
        if thread.get('javaName')!='main':continue
        fs=(v.get('stackTrace') or {}).get('frames',[])
        names=[]
        for f in fs:
            m=f.get('method') or {}; typ=m.get('type') or {}
            names.append((typ.get('name','?')+'.'+m.get('name','?')).replace('/','.'))
        if not names:continue
        if any(n.startswith('java.lang.ThreadLocal') for n in names):
            i=next(i for i,n in enumerate(names) if n.startswith('java.lang.ThreadLocal'))
            caller=next((n for n in names[i:] if not n.startswith('java.lang.ThreadLocal')), '(truncated caller)')
            callers[caller]+=1
        count+=1; leaves[names[0]]+=1;frames.update(set(names));stacks[' <- '.join(names[:12])]+=1
        for k,needles in patterns.items():
            if any(n in x for x in names for n in needles):categories[k]+=1
    out[p.stem]={'mainThreadSamples':count,'topLeaves':leaves.most_common(20),'topInclusiveFrames':frames.most_common(35),
                 'threadLocalCallers':dict(callers.most_common()),'inclusiveCategories':dict(categories),'topStacks':stacks.most_common(12)}
print(json.dumps({'warning':'Inclusive sample categories overlap. Samples are neither wall-time percentages nor ThreadLocal invocation counts. Inlining can hide methods. Diagnostic runs only.', 'profiles':out},indent=2))
